@Test void selectedEmptyArrayMustSurviveTheBridge() {
  provider.get("typed-control").logRecordBuilder().setBody("typed-control")
      .setAttribute(AttributeKey.stringArrayKey("items"), List.of()).emit();
  assertTrue(exporter.getFinishedLogRecordItems().get(0).getAttributes().asMap()
      .containsKey(AttributeKey.stringArrayKey("items")));
  bridge.stop();
  bridge.setKeyValuePairAttributesIncluded("approved,items");
  bridge.start();
  logger.atInfo().addKeyValue("approved", true).addKeyValue("items", List.of())
      .log("bridge-empty-array");
  assertEquals(2, exporter.getFinishedLogRecordItems().size());
  var attributes = exporter.getFinishedLogRecordItems().get(1).getAttributes();
  assertEquals(true, attributes.get(AttributeKey.booleanKey("approved")));
  assertEquals(1, sink.list.size());
  assertTrue(attributes.asMap().containsKey(AttributeKey.stringArrayKey("items")),
      "Bridge lost the selected empty array while typed SDK and approved scalar controls passed: " + attributes);
}
